const AGENT_BOTS = new Set(["rhino-ai-agents[bot]"]);
const LOCKED = [
  ".github/**",                       // workflows, scripts, the PR template
  ".claude/settings.json", "scripts/claude_stop_verify.sh", "frontend/scripts/verify.ts",
  ".flake8", "frontend/biome.json", "frontend/tsconfig.json", "frontend/vitest.config.js",
  "frontend/playwright.config.ts", "cloud/.coveragerc", "sdk/tox.ini",
];

export function lockedFiles(author: string, files: string[]): string[] {
  if (!AGENT_BOTS.has(author)) return [];   // people may change these; the reviewer sees it
  return files.filter((f) => LOCKED.some((pattern) => matchesGlob(f, pattern)));
}

const LOCKED_TOOL_SECTIONS = ["black", "isort", "flake8", "coverage", "pytest"];

export function changedToolSections(baseText: string, headText: string): string[] {
  const tool = (text: string) => (parse(text).tool ?? {}) as Record<string, unknown>;
  const [base, head] = [tool(baseText), tool(headText)];
  return LOCKED_TOOL_SECTIONS.filter((s) => !isDeepStrictEqual(base[s], head[s]));
}

const SKIP_OR_FOCUS =
  /\b(it|test|describe)\.(skip|todo|fixme|only)\(|\bx(it|describe)\(|@pytest\.mark\.(skip|xfail)|@unittest\.skip/;
const ASSERTION = /\bexpect\(|\bassert\b|self\.assert\w+\(|pytest\.raises\(|toThrow|toHaveBeenCalled/;
const THRESHOLD = /(fail[_-]under|thresholds?|retries|timeout)\W+([\d.]+)/i;

// for each + or - line of a test file's diff:
if (sign === "+" && SKIP_OR_FOCUS.test(text)) out.push(["new skip or focus", text.trim()]);
if (sign === "-" && THRESHOLD.test(text)) out.push(["threshold changed: check it was not loosened", text.trim()]);
if (ASSERTION.test(text)) sign === "-" ? (removed += 1) : (added += 1);
// after the loop:
if (removed > added) out.push(["assertions removed", `${removed - added} more assertions removed than added`]);

